Subject: [PATCH] applets/kicker: show the package format of apps installed
 twice

When the same app was installed from different sources, like distro
packages and Flatpak or Snap, the menu listed identical entries. Now a
Flatpak or Snap app sharing its name with another one shows its format.

BUG: 500732
---
 applets/kicker/actionlist.cpp         | 31 +++++++++++++++++++++++++++
 applets/kicker/actionlist.h           |  2 ++
 applets/kicker/appentry.cpp           | 15 +++++++++++++
 applets/kicker/runnermatchesmodel.cpp | 11 ++++++++++
 4 files changed, 59 insertions(+)

diff --git a/applets/kicker/actionlist.cpp b/applets/kicker/actionlist.cpp
index db486ea5e2..4a1bc20966 100644
--- a/applets/kicker/actionlist.cpp
+++ b/applets/kicker/actionlist.cpp
@@ -23,6 +23,7 @@
 #include <KPropertiesDialog>
 #include <KProtocolInfo>
 #include <KRecentDocument>
+#include <KSycoca>

 #include <KIO/DesktopExecParser>
 #include <PlasmaActivities/Stats/Cleaning>
@@ -470,6 +471,36 @@ static QList<KServiceAction> additionalActions(const KService::Ptr &service)
     return actions;
 }

+QString packageFormatIfAmbiguous(const KService::Ptr &service)
+{
+    QString packageFormat;
+    if (!service->property<QString>(QStringLiteral("X-Flatpak")).isEmpty()) {
+        packageFormat = i18nc("@item:intext package format an app was installed from", "Flatpak");
+    } else if (!service->property<QString>(QStringLiteral("X-SnapInstanceName")).isEmpty()) {
+        packageFormat = i18nc("@item:intext package format an app was installed from", "Snap");
+    }
+    if (packageFormat.isEmpty()) {
+        return {};
+    }
+
+    static std::optional<QHash<QString, int>> appNameCounts;
+    if (!appNameCounts) {
+        static const auto connection = QObject::connect(KSycoca::self(), &KSycoca::databaseChanged, [] {
+            appNameCounts.reset();
+        });
+        Q_UNUSED(connection)
+        appNameCounts.emplace();
+        const auto services = KService::allServices();
+        for (const KService::Ptr &other : services) {
+            if (other->isApplication() && !other->noDisplay()) {
+                ++(*appNameCounts)[other->name()];
+            }
+        }
+    }
+
+    return appNameCounts->value(service->name()) > 1 ? packageFormat : QString();
+}
+
 QVariantList additionalAppActions(const KService::Ptr &service)
 {
     QVariantList list;
diff --git a/applets/kicker/actionlist.h b/applets/kicker/actionlist.h
index c7825a692e..602f274ddf 100644
--- a/applets/kicker/actionlist.h
+++ b/applets/kicker/actionlist.h
@@ -61,6 +61,8 @@ bool handleEditApplicationAction(const QString &actionId, const KService::Ptr &s
 QVariantList appstreamActions(const KService::Ptr &service);
 bool handleAppstreamActions(const QString &actionId, const KService::Ptr &service);

+QString packageFormatIfAmbiguous(const KService::Ptr &service);
+
 QVariantList additionalAppActions(const KService::Ptr &service);
 bool handleAdditionalAppActions(const QString &actionId, const KService::Ptr &service, const QVariant &argument);
 }
diff --git a/applets/kicker/appentry.cpp b/applets/kicker/appentry.cpp
index e3c1d4aa5f..59e05f2a44 100644
--- a/applets/kicker/appentry.cpp
+++ b/applets/kicker/appentry.cpp
@@ -461,16 +461,31 @@ QString AppEntry::nameFromService(const KService::Ptr &service, NameFormat nameF
         genericName = comment;
     }

+    // Tells apart the same app installed from different sources, e.g. from distro packages and Flatpak
+    const QString packageFormat = Kicker::packageFormatIfAmbiguous(service);
+
     if (nameFormat == NameOnly || genericName.isEmpty() || name == genericName) {
+        if (!packageFormat.isEmpty()) {
+            return i18nc("App name (package format)", "%1 (%2)", name, packageFormat);
+        }
         return name;
     } else if (nameFormat == GenericNameOnly) {
+        if (!packageFormat.isEmpty()) {
+            return i18nc("Generic name (package format)", "%1 (%2)", genericName, packageFormat);
+        }
         return genericName;
     } else if (nameFormat == NameAndGenericName) {
         if (comment.isEmpty()) {
             comment = genericName;
         }
+        if (!packageFormat.isEmpty()) {
+            return i18nc("App name (Comment or Generic name, package format)", "%1 (%2, %3)", name, comment, packageFormat);
+        }
         return i18nc("App name (Comment or Generic name)", "%1 (%2)", name, comment);
     } else {
+        if (!packageFormat.isEmpty()) {
+            return i18nc("Generic name (App name, package format)", "%1 (%2, %3)", genericName, name, packageFormat);
+        }
         return i18nc("Generic name (App name)", "%1 (%2)", genericName, name);
     }
 }
